import SwiftUI
import Observation

@Observable
final class SearchModel {
    var query: String = ""
    var results: [Item] = []

    func search() async {
        results = await API.search(query)
    }
}

struct SearchView: View {
    @State private var model = SearchModel()

    var body: some View {
        VStack {
            SearchBar(text: $model.query, onSubmit: { Task { await model.search() } })
            List(model.results) { item in Text(item.title) }
        }
    }
}

struct SearchBar: View {
    @Binding var text: String
    var onSubmit: () -> Void

    var body: some View {
        TextField("Buscar", text: $text)
            .onSubmit(onSubmit)
    }
}

struct ProductCard: View {
    let product: Product

    var body: some View {
        HStack(spacing: 12) {
            AsyncImage(url: product.imageURL) { img in
                img.resizable().aspectRatio(contentMode: .fill)
            } placeholder: { Color.gray.opacity(0.2) }
            .frame(width: 80, height: 80)
            .clipShape(RoundedRectangle(cornerRadius: 8))

            VStack(alignment: .leading, spacing: 4) {
                Text(product.name).font(.headline)
                Text(product.price, format: .currency(code: "BRL"))
                    .font(.subheadline).foregroundStyle(.secondary)
            }
            Spacer()
        }
        .padding()
        .background(.regularMaterial, in: RoundedRectangle(cornerRadius: 12))
    }
}

enum Route: Hashable {
    case productList
    case productDetail(id: UUID)
    case checkout
}

@Observable
final class Router {
    var path: [Route] = []
    func push(_ r: Route) { path.append(r) }
    func popToRoot() { path.removeAll() }
}

struct AppShell: View {
    @State private var router = Router()

    var body: some View {
        NavigationStack(path: $router.path) {
            HomeView()
                .navigationDestination(for: Route.self) { route in
                    switch route {
                    case .productList:          ProductListView()
                    case .productDetail(let id): ProductDetailView(id: id)
                    case .checkout:             CheckoutView()
                    }
                }
        }
        .environment(router)
    }
}

struct FeedView: View {
    let posts: [Post]

    var body: some View {
        ScrollView {
            LazyVStack(spacing: 12) {
                ForEach(posts) { post in
                    PostRow(post: post)
                        .onAppear { if post == posts.last { loadMore() } }
                }
            }
            .padding()
        }
    }

    func loadMore() { /* paginacao */ }
}

import UIKit

struct RichTextView: UIViewRepresentable {
    @Binding var attributed: NSAttributedString

    func makeUIView(context: Context) -> UITextView {
        let v = UITextView()
        v.isEditable = true
        v.delegate = context.coordinator
        return v
    }
    func updateUIView(_ uiView: UITextView, context: Context) {
        uiView.attributedText = attributed
    }
    func makeCoordinator() -> Coordinator { Coordinator(self) }

    final class Coordinator: NSObject, UITextViewDelegate {
        var parent: RichTextView
        init(_ p: RichTextView) { parent = p }
        func textViewDidChange(_ textView: UITextView) {
            parent.attributed = textView.attributedText
        }
    }
}
